<section class="metrics-grid">
  <?php $stats = [['Tổng đầu sách', $bookMetrics['title_count'] ?? 0, '▤', 'title'], ['Tổng bản sách', $bookMetrics['copy_count'] ?? 0, '▧', 'copy'], ['Có thể cho mượn', $bookMetrics['available_count'] ?? 0, '✳', 'available'], ['Đang được mượn', $bookMetrics['loaned_count'] ?? 0, '⇄', 'borrowed'], ['Độc giả hoạt động', $readerMetrics['reader_count'] ?? 0, '♙', 'readers'], ['Phiếu đang mở', $loanMetrics['active_loan_count'] ?? 0, '◷', 'loans'], ['Phiếu quá hạn', $loanMetrics['overdue_loan_count'] ?? 0, '!', 'overdue'], ['Yêu cầu đặt trước', $reservations ?? 0, '↗', 'reservations'], ['Dư nợ phí', $outstandingFineBalance ?? 0, '₫', 'fines']]; foreach ($stats as [$label, $value, $icon, $class]): ?>
  <article class="metric-card"><span class="metric-icon metric-<?= e($class === 'fines' ? 'copy' : $class) ?>"><?= e($icon) ?></span><span class="metric-label"><?= e($label) ?></span><strong><?= $class === 'fines' ? number_format((float) $value, 0, ',', '.') : number_format((int) $value) ?><?= $class === 'fines' ? '<small class="currency">đ</small>' : '' ?></strong><?php if ($class === 'overdue' && (int) $value > 0): ?><a class="metric-note alert-text" href="<?= e(url('/admin/loans?status=overdue')) ?>">Cần xử lý ngay →</a><?php elseif ($class === 'fines' && (float) $value > 0): ?><a class="metric-note alert-text" href="<?= e(url('/admin/fines')) ?>">Xem các khoản phí →</a><?php else: ?><span class="metric-note">Cập nhật theo dữ liệu thư viện</span><?php endif; ?></article>
  <?php endforeach; ?>
</section>
<div class="dashboard-columns">
