  </section>
  <section class="panel"><div class="panel-heading"><div><span class="eyebrow">ĐƯỢC MƯỢN NHIỀU</span><h2>Sách được yêu thích</h2></div><a class="text-link" href="<?= e(url('/admin/books')) ?>">Danh mục <span>→</span></a></div>
    <?php if ($popularBooks): ?><div class="popular-list"><?php foreach ($popularBooks as $book): ?><a class="popular-row" href="<?= e(url('/book/' . $book['id'])) ?>"><span class="popular-cover"><?= e(mb_strtoupper(mb_substr($book['title'], 0, 1))) ?></span><span><strong><?= e($book['title']) ?></strong><small><?= e($book['author']) ?></small></span><span class="availability <?= (int) $book['available_copies'] > 0 ? 'is-available' : 'is-unavailable' ?>"><?= (int) $book['available_copies'] > 0 ? 'Còn sách' : 'Đang mượn' ?></span></a><?php endforeach; ?></div><?php else: ?><div class="empty-inline">Chưa có dữ liệu mượn sách.</div><?php endif; ?>
  </section>
</div>
<section class="panel dashboard-chart-panel"><div class="panel-heading"><div><span class="eyebrow">NHỊP ĐỌC 6 THÁNG GẦN NHẤT</span><h2>Lượt mượn theo tháng</h2></div><a class="text-link" href="<?= e(url('/admin/statistics')) ?>">Xem thống kê <span>→</span></a></div><?php if ($monthly): ?><?php $monthlyMax = max(1, ...array_map(static fn($item) => (int) $item['loan_count'], $monthly)); ?><div class="bar-chart" role="img" aria-label="Biểu đồ lượt mượn sách theo tháng"><?php foreach ($monthly as $item): ?><div class="bar-column"><strong><?= (int) $item['loan_count'] ?></strong><span style="height:<?= max(4, round((int) $item['loan_count'] * 150 / $monthlyMax)) ?>px"></span><small><?= e(date('m/Y', strtotime($item['month_key'] . '-01'))) ?></small></div><?php endforeach; ?></div><?php else: ?><div class="empty-inline">Chưa có dữ liệu lượt mượn trong khoảng thời gian này.</div><?php endif; ?></section>
<div class="dashboard-columns">
  <section class="panel"><div class="panel-heading"><div><span class="eyebrow">PHIẾU MƯỢN</span><h2>Mới cập nhật</h2></div><a class="text-link" href="<?= e(url('/admin/loans')) ?>">Tất cả phiếu <span>→</span></a></div>
    <?php if ($recentLoans): ?><div class="table-scroll"><table><thead><tr><th>Độc giả</th><th>Sách</th><th>Hạn trả</th><th>Trạng thái</th></tr></thead><tbody><?php foreach ($recentLoans as $loan): ?><tr><td><strong><?= e($loan['full_name']) ?></strong><small><?= e($loan['loan_code']) ?></small></td><td><?= e($loan['book_title']) ?></td><td><?= e(format_date($loan['due_at'])) ?></td><td><span class="status-pill <?= e($loan['loan_status']) ?>"><?= $loan['loan_status'] === 'returned' ? 'Đã trả' : ($loan['loan_status'] === 'overdue' ? 'Quá hạn' : 'Đang mượn') ?></span></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty-inline">Chưa có phiếu mượn nào.</div><?php endif; ?>
  </section>
  <section class="panel"><div class="panel-heading"><div><span class="eyebrow">KHO SÁCH</span><h2>Theo thể loại</h2></div><a class="text-link" href="<?= e(url('/admin/categories')) ?>">Quản lý <span>→</span></a></div>
    <?php if ($categoryStats): ?><div class="category-stat-list"><?php $maxTitles = max(1, ...array_map(static fn($item) => (int) $item['title_count'], $categoryStats)); foreach (array_slice($categoryStats, 0, 6) as $category): ?><div><div><strong><?= e($category['name']) ?></strong><span><?= (int) $category['title_count'] ?> đầu sách</span></div><div class="progress-track"><span style="width:<?= min(100, round((int) $category['title_count'] * 100 / $maxTitles)) ?>%"></span></div></div><?php endforeach; ?></div><?php else: ?><div class="empty-inline">Hãy thêm thể loại để tổ chức danh mục sách.</div><?php endif; ?>
  </section>
</div>
